MAX_RETRIES = 3


def fetch_with_retry(client, url):
    """GET url, retrying up to MAX_RETRIES times on connection errors."""
    for attempt in range(MAX_RETRIES):
        try:
            return client.get(url)
        except ConnectionError:
            if attempt == MAX_RETRIES - 1:
                raise
    return None

